return {
  -- base46: dynamic theme generated by DankMaterialShell (when on DMS)
  { "AvengeMedia/base46", lazy = true, opts = {} },

  -- Catppuccin Mocha fallback (used when noctalia/dms dynamic theme is not generated yet)
  { "catppuccin/nvim", name = "catppuccin", priority = 1000 },
  { "folke/tokyonight.nvim", enabled = false },

  -- Use noctalia colorscheme if generated by Noctalia, else dms if present, else catppuccin-mocha
  {
    "LazyVim/LazyVim",
    opts = {
      colorscheme = function()
        local noctalia_color = vim.fn.stdpath("config") .. "/colors/noctalia.lua"
        if vim.uv.fs_stat(noctalia_color) then
          vim.cmd.colorscheme("noctalia")
        elseif pcall(vim.cmd.colorscheme, "dms") then
          return
        else
          vim.cmd.colorscheme("catppuccin-mocha")
        end
      end,
    },
  },
}
